// Check the shared secret and the required fields. Nothing is sent to Karsa unless this passes.
const req = $input.first().json;
const b = req.body || {};
const secret = $env.KARSA_INTAKE_SECRET || '';
const sent = (req.headers || {})['x-intake-secret'] || '';
if (!secret || sent !== secret) {
  return [{ json: { valid: false, unauthorized: true, request_id: null, missing: [], reasons: ['Missing or wrong X-Intake-Secret header.'] } }];
}
const str = (k) => (typeof b[k] === 'string' ? b[k].trim() : '');
const missing = ['request_id', 'title', 'client_name', 'brief'].filter((k) => !str(k));
const problems = [];
if (str('request_id') && !/^[A-Za-z0-9._:-]{4,100}$/.test(str('request_id'))) problems.push('request_id may only use letters, digits, ".", "_", ":" or "-" (4-100 characters).');
if (str('title') && str('title').length < 3) problems.push('title needs at least 3 characters.');
if (str('client_name') && str('client_name').length < 2) problems.push('client_name needs at least 2 characters.');
if (str('brief') && str('brief').length < 20) problems.push('brief is under 20 characters, too short to review.');
const valid = missing.length === 0 && problems.length === 0;
return [{ json: {
  valid,
  unauthorized: false,
  request_id: str('request_id') || null,
  source: str('source') || 'webhook',
  missing,
  reasons: [...missing.map((m) => `Missing required field: ${m}`), ...problems],
  case: { title: str('title'), client_name: str('client_name'), brief: typeof b.brief === 'string' ? b.brief : '' },
  idempotency_key: valid ? `n8n-${str('request_id')}` : null,
} }];

// Mock notification: append one JSON line to a local file. No email, chat or WhatsApp.
const fs = require('fs');
const v = $input.first().json;
const entry = { at: new Date().toISOString(), channel: 'mock-notify', status: v.unauthorized ? 'rejected_unauthorized' : 'needs_human', stage: 'payload', request_id: v.request_id, case_code: null, reasons: v.reasons };
fs.appendFileSync('/files/notifications.jsonl', JSON.stringify(entry) + '\n');
return [{ json: { ...entry, http: v.unauthorized ? 401 : 422 } }];

// Karsa's own extraction decides what is unclear: critical requirements that are MISSING or
// CONFLICTING, or a flag such as a possible prompt injection. Either way the case stays a draft.
const created = $('Karsa: create draft case').last().json;
const detail = $input.first().json;
const replay = created.statusCode === 200;
const gaps = (detail.requirements || []).filter((r) => r.critical && ['MISSING', 'CONFLICTING'].includes(r.state)).map((r) => `${r.label}: ${r.state.toLowerCase()}`);
const flags = (detail.flags || []).map((f) => `Flag: ${f.kind.replace(/_/g, ' ')}`);
const reasons = [...gaps, ...flags];
const status = replay ? 'already_received' : reasons.length ? 'needs_human' : 'draft_created';
return [{ json: {
  status,
  http: replay ? 200 : reasons.length ? 202 : 201,
  request_id: $('Validate request').first().json.request_id,
  case_code: detail.code,
  case_status: detail.status_label,
  reasons,
  approval: 'Not requested. Approval happens in Karsa with its own approver rules.',
} }];

const fs = require('fs');
const v = $input.first().json;
const entry = { at: new Date().toISOString(), channel: 'mock-notify', status: 'needs_human', stage: 'review', request_id: v.request_id, case_code: v.case_code, reasons: v.reasons };
fs.appendFileSync('/files/notifications.jsonl', JSON.stringify(entry) + '\n');
return [{ json: v }];

const fs = require('fs');
const v = $input.first().json;
const entry = { at: new Date().toISOString(), channel: 'mock-notify', status: v.status, stage: 'draft', request_id: v.request_id, case_code: v.case_code, reasons: v.reasons };
fs.appendFileSync('/files/notifications.jsonl', JSON.stringify(entry) + '\n');
return [{ json: v }];

// Exponential backoff: 1 s, 2 s, 4 s, then give up. Only connection errors, timeouts, 408, 429
// and 5xx are retried; any other 4xx from Karsa is a real refusal and goes to a person instead.
const MAX_RETRIES = 3;
const attempt = $runIndex + 1;
const err = $input.first().json.error || $input.first().json || {};
const text = JSON.stringify(err);
const found = text.match(/\b(40[0-9]|41[0-9]|42[0-9]|5[0-9]{2})\b/);
const status = Number(err.httpCode || err.status || (found ? found[1] : 0)) || 0;
// Karsa errors look like {"error":{"code":...,"message":...}}; keep only the readable message.
const inner = text.match(/message\\*":\\*"([^"\\]+)/g) || [];
const karsaMessage = inner.length > 1 ? inner[inner.length - 1].replace(/^message\\*":\\*"/, '') : null;
const transient = status === 0 || status === 408 || status === 429 || status >= 500;
const decision = !transient ? 'rejected' : attempt <= MAX_RETRIES ? 'retry' : 'give_up';
return [{ json: {
  decision,
  attempt,
  delay_seconds: 2 ** (attempt - 1),
  karsa_status: status || null,
  message: String(karsaMessage || err.message || err.description || 'Karsa did not answer').slice(0, 300),
} }];

const fs = require('fs');
const v = $input.first().json;
const req = $('Validate request').first().json;
const entry = { at: new Date().toISOString(), channel: 'mock-notify', status: 'needs_human', stage: 'refused_by_karsa', request_id: req.request_id, case_code: null, reasons: [`Karsa answered ${v.karsa_status}: ${v.message}`] };
fs.appendFileSync('/files/notifications.jsonl', JSON.stringify(entry) + '\n');
return [{ json: { ...entry, http: v.karsa_status === 409 ? 409 : 422 } }];

// Dead letter: keep the full request so it can be replayed later with the same Idempotency-Key.
const fs = require('fs');
const v = $input.first().json;
const req = $('Validate request').first().json;
const entry = { at: new Date().toISOString(), status: 'dead_letter', attempts: v.attempt, last_error: v.message, request_id: req.request_id, idempotency_key: req.idempotency_key, case: req.case };
fs.appendFileSync('/files/dead-letter.jsonl', JSON.stringify(entry) + '\n');
return [{ json: { status: 'dead_letter', request_id: req.request_id, attempts: v.attempt, reasons: [`Karsa unavailable after ${v.attempt} attempts: ${v.message}`], http: 503 } }];
